values ('dialog_fq_iron_019', 'fq_iron_019', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. No Anomalies in Our Territory — A Resonance Echo", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Resonance Echo; Defeat 2x War Machine Sentinel\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 800 EXP · 450 Currency · 225 CRD · 450 Reputation · Entropy Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 249)
