values ('dialog_fq_iron_049', 'fq_iron_049', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. The Shattered Heart is the enemy''s core territory", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to SHATTERED_HEART; Collect 1x Establish the breach head.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 2500 EXP · 1300 Currency · 650 CRD · 800 Reputation · Con Elite Recovery Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 279)
