values ('dialog_fq_iron_052', 'fq_iron_052', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "You''ve got that look — ready for something harder. Operation Total Void Control is authorized", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 8x Void Reaver; Defeat 5x Aethel Void Channeler\n\nStrength prevails.\n\nRewards: 4500 EXP · 2200 Currency · 1100 CRD · 1500 Reputation · Void Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 282)
