values ('dialog_fq_iron_062', 'fq_iron_062', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "You''ve got that look — ready for something harder. Aethel Iron Carapaces have armor that rivals Hegemony steel", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 8x Aethel Iron Carapace; Collect 3x Collect armor samples for the forges.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 5200 EXP · 2600 Currency · 1300 CRD · 1700 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 292)
