values ('dialog_fq_iron_090', 'fq_iron_090', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. Activate the World Engine", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 10x Aethel Abyssal Reaver; Defeat 2x Crystal Tyrant; Collect 1x Confirm Engine activation.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 320)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_iron_091', 'fq_iron_091', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. With the Engine online, remaining hostiles are flushed to the surface", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 5x Gigantic Jotunn; Defeat 8x Aethel Iron Carapace\n\nStrength prevails.\n\nRewards: 10000 EXP · 5000 Currency · 2500 CRD · 3200 Reputation · Stabilizer Gyro Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 321)
