insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_iron_097', 'fq_iron_097', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. The Final Campaign — The Hegemony launches the Final Campaign to eliminate all significant threats", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Gigantic Jotunn; Defeat 1x Abyss Harbinger; Collect 1x Confirm Final Campaign complete.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 15000 EXP · 7500 Currency · 3750 CRD · 5000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 327)
