values ('dialog_fq_merid_005', 'fq_merid_005', 'npc_meridian_class_trainer', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Don Vercelli Mox reviews quarterly performance with the same dispassion he ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Speak with npc_meridian_class_trainer; Speak with class_change_screen; Defeat 3x Cave Rat\n\nThe Cartel pays well for results, Associate.\n\nRewards: 400 EXP · 200 Currency · 150 Reputation · Wpn Hunter Dagger + Arm Leather Tunic", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 335)
