values ('dialog_fq_merid_006', 'fq_merid_006', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. The Smuggler Jungle is the one zone on Xylos where goods move without oversight", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to SMUGGLER_JUNGLE; Collect 1x Deploy a trading post beacon.\n\nThe Cartel pays well for results, Associate.\n\nRewards: 100 EXP · 60 Currency · 60 Reputation · Con Nutrient Ration", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 336)
