values ('dialog_fq_merid_008', 'fq_merid_008', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Associate! Just who I wanted to see. Written Off — Swamp Rippers", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Swamp Ripper; Collect 3x Collect Ripper hide — still tradable.\n\nThe Cartel pays well for results, Associate.\n\nRewards: 180 EXP · 100 Currency · 100 Reputation · Raw Hide", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 338)
