values ('dialog_fq_merid_015', 'fq_merid_015', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Madam Z conducts the Black Dock''s quarterly audit with the thoroughness of ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 4x Black Dock Smuggler; Defeat 4x Black Dock Assassin\n\nThe Cartel pays well for results, Associate.\n\nRewards: 500 EXP · 280 Currency · 300 Reputation · Scrap Circuit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 345)
