values ('dialog_fq_merid_018', 'fq_merid_018', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Associate! Just who I wanted to see. There Is Only One Cartel — A coordinated Enforcer syndicate", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 5x Black Dock Enforcer; Collect 1x Seize their operations ledger.\n\nSimple. Profitable. Done.\n\nRewards: 600 EXP · 330 Currency · 165 CRD · 350 Reputation · Tactical Sensor Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 348)
