values ('dialog_fq_merid_024', 'fq_merid_024', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Aethel Behemoths are living capital", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 2x Aethel Behemoth; Collect 1x File the organ harvesting manifest.\n\nSimple. Profitable. Done.\n\nRewards: 850 EXP · 460 Currency · 230 CRD · 480 Reputation · Mutant Heart Tissue", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 354)
