values ('dialog_fq_merid_029', 'fq_merid_029', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Cradle Sentinel variants have been discovered", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 4x Cradle Sentinel; Collect 1x Complete the Sentinel variant catalog.\n\nSimple. Profitable. Done.\n\nRewards: 850 EXP · 480 Currency · 240 CRD · 480 Reputation · Stabilizer Gyro Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 359)
